<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{ScheduleItem,Department,Teacher};use Illuminate\Http\Request;class ScheduleController extends Controller{public function index(Request $r){$q=ScheduleItem::with(['department','teacher']);if($r->filled('department'))$q->where('department_id',$r->integer('department'));if($r->filled('teacher'))$q->where('teacher_id',$r->integer('teacher'));return view('admin.schedule.index',['items'=>$q->orderBy('weekday')->orderBy('starts_at')->paginate(50)->withQueryString(),'departments'=>Department::orderBy('sort')->get(),'teachers'=>Teacher::orderBy('name')->get()]);}public function create(){return $this->form(new ScheduleItem);}public function store(Request $r){ScheduleItem::create($this->data($r));return redirect()->route('admin.schedule.index')->with('ok','Занятие добавлено');}public function edit(ScheduleItem $schedule){return $this->form($schedule);}public function update(Request $r,ScheduleItem $schedule){$schedule->update($this->data($r));return redirect()->route('admin.schedule.index')->with('ok','Занятие сохранено');}public function destroy(ScheduleItem $schedule){$schedule->delete();return back();}private function form($item){return view('admin.schedule.form',['item'=>$item,'departments'=>Department::orderBy('sort')->get(),'teachers'=>Teacher::orderBy('name')->get()]);}private function data(Request $r){$d=$r->validate(['department_id'=>'nullable|exists:departments,id','teacher_id'=>'nullable|exists:teachers,id','group_name'=>'nullable|max:255','subject'=>'required|max:255','room'=>'nullable|max:100','weekday'=>'required|integer|between:1,7','starts_at'=>'required','ends_at'=>'nullable','sort'=>'nullable|integer']);$d['is_active']=$r->boolean('is_active');return $d;}}